create table wksp_dtesc.sgt_racks (
    id               number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    sala_id          number not null enable,
    nombre           varchar2(255 byte) not null enable,
    detalle          varchar2(4000 byte),
    unidad_encargada varchar2(50 byte),
    marca            varchar2(255 byte),
    modelo           varchar2(255 byte),
    dimensiones      varchar2(255 byte),
    creado_por       varchar2(255 byte),
    creado_el        timestamp(6),
    modificado_por   varchar2(255 byte),
    modificado_el    timestamp(6),
    altura_u         number(2, 0)
);

alter table wksp_dtesc.sgt_racks
    add constraint sgt_racks_altura_u_ck check ( altura_u between 1 and 60 ) enable;

alter table wksp_dtesc.sgt_racks add primary key ( id )
    using index enable;


